// the retained phase A synthetic-speech recording in real private OSS. Never purge it.
require __DIR__.'/../../bin/bootstrap.php';
use Illuminate\Support\Facades\{DB,Hash};use Illuminate\Support\Str;
use App\Storage\{OssConfiguration,StorageRegistry};
if(!app()->environment('testing')||config('database.connections.pgsql.database')!=='classroom_test')throw new RuntimeException('C fixture requires isolated classroom_test');
$metadata=json_decode(file_get_contents($argv[1]??throw new RuntimeException('source_metadata_required')),true,flags:JSON_THROW_ON_ERROR);
if(!preg_match('/^classroom_integration_[a-f0-9]{12}$/D',$metadata['database']))throw new RuntimeException('source_database_invalid');
$connection=config('database.connections.pgsql');$pdo=new PDO('pgsql:host='.$connection['host'].';port='.$connection['port'].';dbname='.$metadata['database'],$connection['username'],$connection['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
$recording=$pdo->query("SELECT * FROM recordings WHERE status='playable' ORDER BY id DESC LIMIT 1")->fetch(PDO::FETCH_ASSOC);if(!$recording)throw new RuntimeException('source_playable_recording_required');
$oss=config('classroom.oss');$oss['prefix']=$metadata['prefix'];$cfg=new OssConfiguration($oss);if($cfg->version()!==$recording['storage_version'])throw new RuntimeException('source_storage_version_mismatch');StorageRegistry::register($oss);
config(['hashing.bcrypt.rounds'=>4]);$suffix=bin2hex(random_bytes(6));$accounts=[];
foreach(['admin','member']as$type){$student='0000-C-fixture-'.$type.'-'.$suffix;$password='Fixture-password-2026';$uid=DB::table('users')->insertGetId(['name'=>'SYNTHETIC C '.$type.' Ї','student_id'=>$student,'password'=>Hash::make($password),'role'=>$type==='admin'?'admin':'user','must_change_password'=>false]);$accounts[$type]=['id'=>$uid,'student_id'=>$student,'password'=>$password];}
